def compress_string(s):
    if not s:
        return ""

    compressed = []
    count = 1

    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            count += 1
        else:
            compressed.append(s[i - 1] + str(count))
            count = 1

    # Append the last run
    compressed.append(s[-1] + str(count))

    return ''.join(compressed)

# Example usage:
print(compress_string('aaabb'))  # Output: 'a3b2'
```

