def caesar_shift(s, n):
    def shift_char(c):
        if 'a' <= c <= 'z':
            return chr((ord(c) - ord('a') + n) % 26 + ord('a'))
        elif 'A' <= c <= 'Z':
            return chr((ord(c) - ord('A') + n) % 26 + ord('A'))
        else:
            return c

    return ''.join(shift_char(c) for c in s)

# Example usage:
print(caesar_shift("hello world!", 3))  # Output: "khoor zruog!"
print(caesar_shift("ABC DEF!", -3))    # Output: "XZY UVW!"
```

