def first_unique_char(s):
    char_count = {}

    # Count the occurrences of each character
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Find the first character that occurs exactly once
    for char in s:
        if char_count[char] == 1:
            return char

    return None

# Example usage:
s = "leetcode"
print(first_unique_char(s))  # Output: 'l'
