def second_largest(nums):
    if len(nums) < 2:
        return None

    first, second = float('-inf'), float('-inf')
    seen = set()

    for num in nums:
        if num not in seen:
            seen.add(num)
            if num > first:
                second = first
                first = num
            elif num > second:
                second = num

    return second if second != float('-inf') else None
```

