def prime_factors(n):
    factors = []
    # Start with the smallest prime number
    divisor = 2
    while n >= 2:
        while n % divisor == 0:
            factors.append(divisor)
            n //= divisor
        divisor += 1
        if divisor * divisor > n:
            if n > 1:
                factors.append(n)
                break
    return sorted(factors)

# Example usage:
n = 60
print(prime_factors(n))  # Output: [2, 2, 3, 5]
```

