def count_pairs_sum(nums, target):
    count = 0
    n = len(nums)

    # Use a dictionary to store the frequency of each number
    num_count = {}

    for i in range(n):
        complement = target - nums[i]
        if complement in num_count:
            count += num_count[complement]
        if nums[i] in num_count:
            num_count[nums[i]] += 1
        else:
            num_count[nums[i]] = 1

    return count

# Example usage:
nums = [1, 5, 7, -1, 5]
target = 6
print(count_pairs_sum(nums, target))  # Output should be 4
```

